#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef long double ld;
const int mod = (int)1e9 + 7;

int add_mod(int a, int b) {
    int s = a + b;
    if (s >= mod) s -= mod;
    return s;
}

int subtract_mod(int a, int b) {
    int s = a - b;
    if (s < 0) s += mod;
    return s;
}

int multiply_mod(int a, int b) {
    return (1LL * a * b) % mod;
}

ll n;
int k;
vector<vector<int>> matrix_multiply(const vector<vector<int>>& a, const vector<vector<int>>& b) {
    vector<vector<int>> c(k + 1, vector<int>(k + 1, 0));
    for (int i = 0; i <= k; i++) {
        for (int j = 0; j <= k; j++) {
            for (int t = 0; t <= k; t++) {
                c[i][t] = add_mod(c[i][t], multiply_mod(a[i][j], b[j][t]));
            }
        }
    }
    return c;
}

vector<vector<int>> pref[100];

vector<vector<int>> shift_matrix(const vector<vector<int>>& mat) {
    vector<vector<int>> c(k + 1, vector<int>(k + 1, 0));
    for (int i = 0; i <= k; i++) {
        for (int j = 0; j <= k; j++) {
            int ni = i;
            if (ni < k) ni = (ni + k - 1) % k;
            int nj = j;
            if (nj < k) nj = (nj + k - 1) % k;
            c[i][j] = mat[ni][nj];
        }
    }
    return c;
}

void print_matrix(const vector<vector<int>>& c) {
    for (auto row : c) {
        for (int v : row) cout << v << " ";
        cout << '\n';
    }
    cout << "------------" << endl;
}

void initialize() {
    ll temp = n;
    int digits = 0;
    while (temp > 0) {
        temp /= k;
        digits++;
    }
    pref[0].resize(k + 1, vector<int>(k + 1, 0));
    for (int i = 1; i < k; i++) {
        pref[0][i][i] = 1;
    }
    pref[0][0][k] = 1;
    pref[0][k][0] = mod - 1;
    pref[0][k][k] = 2;

    for (int step = 0; step < digits; step++) {
        pref[step + 1] = pref[step];
        auto current = pref[step];
        for (int i = 1; i <= k - 1; i++) {
            current = shift_matrix(current);
            pref[step + 1] = matrix_multiply(pref[step + 1], current);
        }
    }
}

vector<vector<int>> compute_matrix(ll n_value) {
    if (n_value == 0) {
        vector<vector<int>> c(k + 1, vector<int>(k + 1, 0));
        for (int i = 0; i <= k; i++) c[i][i] = 1;
        return c;
    }
    ll power = 1;
    int d = 0;
    while (power <= n_value / k) {
        power *= k;
        d++;
    }
    if (n_value == power) return pref[d];
    ll steps = n_value / power;
    ll left = n_value - steps * power;
    auto current_matrix = compute_matrix(0);
    auto current_coef = pref[d];
    for (int i = 0; i < steps; i++) {
        current_matrix = matrix_multiply(current_matrix, current_coef);
        current_coef = shift_matrix(current_coef);
    }
    auto remaining_matrix = compute_matrix(left);
    for (int i = 0; i < steps; i++) {
        remaining_matrix = shift_matrix(remaining_matrix);
    }
    return matrix_multiply(current_matrix, remaining_matrix);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> k;
    initialize();
    auto result = compute_matrix(n);
    cout << result[k][k];
    return 0;
}
